  // -------------------------------------------------------------- flashcards
  const FLASH = [
    { id: 'c09-01', kind: 'concepto', q: '¿Por dónde abres el caso de fraude y por qué no por el modelo?',
      a: 'Por el <b>dinero</b>: cuánto se pierde hoy (≈ 12 bps ≈ US$11 M/mes), qué decisiones existen (aprobar, step-up, rechazar, revisión) y cuánto cuesta cada error. Eso define umbrales y evaluación. Después, ubicar el chequeo dentro de la autorización (100 ms, fallback).' },
    { id: 'c09-02', kind: 'numero', q: 'Tráfico y fraude del caso.',
      a: '10 M tx/día → ≈ 116 TPS promedio, ≈ 350 pico diario, <b>2,000 TPS de diseño</b>. Ticket ≈ US$30 → ≈ US$9 B/mes. Fraude ≈ 0.08 % por conteo (≈ 8,000/día, ticket medio ≈ US$45) y 12 bps del valor (≈ US$10.8 M/mes) + ≈ US$3.6 M de fees ≈ <b>US$48 por 1,000 transacciones</b>.' },
    { id: 'c09-03', kind: 'numero', q: 'Costo esperado de aprobar, step-up y rechazar con p = 0.05 y ticket de US$30.',
      a: 'Aprobar: 0.05 × 45 = US$2.25. Step-up (20 % del fraude pasa el challenge, 15 % de abandono, FP = US$7.5): 0.05 × 0.20 × 45 + 0.95 × 0.15 × 7.5 ≈ <b>US$1.52</b>. Rechazar: 0.95 × 7.5 ≈ US$7.13. Gana el step-up.' },
    { id: 'c09-04', kind: 'trampa', q: '¿Por qué rechazar el 0.5 % más riesgoso puede ser peor que no tener modelo?',
      a: 'Con 0.08 % de fraude, casi todo lo que rechazas es bueno: 0.5 % son ≈ 4.7 clientes buenos por 1,000 × US$7.5 ≈ US$35, y en la curva ilustrativa el costo total sube de US$48 a ≈ US$60.7. Cada punto de rechazos cuesta ≈ US$75 por 1,000, más que todo el fraude.' },
    { id: 'c09-05', kind: 'concepto', q: '¿Por qué los umbrales son por segmento?',
      a: 'Porque el costo de un falso negativo crece con el ticket y el de un falso positivo casi no. Step-up conviene desde p ≈ 3.4 % con US$25, ≈ 0.53 % con US$250 y ≈ 0.14 % con US$1,000; rechazar, desde ≈ 44 %, 11 % y 3 %. Son los umbrales de <code>retail_low</code> y <code>retail_high</code> en la política de la referencia. Segmento = giro × rango de ticket, con tope de rechazos.' },
    { id: 'c09-06', kind: 'numero', q: 'Presupuesto de latencia del chequeo.',
      a: 'p99 ≤ 100 ms en el orquestador; 80 ms internos. Red + parseo ≈ 5 ms; caché de decisiones ≤ 5 ms; contadores síncronos (timeout 20) <b>en paralelo</b> con features (timeout 25, ≈ 10–20 ms); GBDT ≈ 2–5 ms (timeout 10); reglas ≈ 1–5 ms; decisión &lt; 1 ms. Esperado ≈ 35–50 ms. Kafka y el challenger, fuera del camino.' },
    { id: 'c09-07', kind: 'concepto', q: '¿Por qué hay contadores síncronos si ya existe Flink?',
      a: 'Flink llega con ≈ 2–10 s de atraso; un card testing de 30 intentos por minuto se come varios intentos por ráfaga en ese hueco. Unas pocas features de segundos a 1 h (en la referencia, cinco: tarjeta, dispositivo, IP) se actualizan en el request con un script atómico por entidad, en buckets de 10 s y 1 min; minutos a días, Flink; semanas, batch.' },
    { id: 'c09-08', kind: 'trampa', q: 'El orquestador da timeout y reintenta el mismo pago. ¿Qué se rompe si no lo previste?',
      a: 'Los contadores de velocidad cuentan dos veces y un límite duro rechaza a un cliente bueno, justo cuando el sistema está lento. Y el reintento podría recibir otra decisión. Defensas: caché de decisiones por <code>payment_id</code> (misma respuesta), guardia por entidad en el script de contadores (SET NX EX de 15 min antes de sumar) y deduplicación por id de evento en Flink.' },
    { id: 'c09-09', kind: 'trampa', q: '¿Cuál es “la trampa clásica” de las features de conteo online vs offline?',
      a: 'Incluir la transacción actual en sus propios agregados en un lado y no en el otro. Todo conteo queda corrido en 1. Convención: excluirla en los dos lados (online, el contador devuelve el valor previo al incremento; offline, ventana abierta en t).' },
    { id: 'c09-10', kind: 'concepto', q: 'Ventana de madurez: ¿qué es y qué número usa el caso?',
      a: 'El tiempo que esperas antes de tratar una cohorte como etiquetada. Supuesto: ≈ 60 % de los contracargos en 30 días, ≈ 90 % en 60, ventanas de hasta ≈ 120. Se entrena y evalúa con cohortes de ≥ 60–90 días; las filas inmaduras se excluyen, no se marcan como negativas.' },
    { id: 'c09-11', kind: 'trampa', q: '“Contracargos de la tarjeta en 90 días” como feature: ¿qué puede salir mal?',
      a: 'Leakage: si la calculas con la tabla de hoy, una transacción fraudulenta cuenta su propio contracargo (que llegó después). Se cuenta por <b>fecha de llegada</b>: solo los contracargos que llegaron antes de t (<a href="#m09.leakage">M9</a>).' },
    { id: 'c09-12', kind: 'concepto', q: 'Reject inference: el problema y la solución del caso.',
      a: 'Lo rechazado nunca recibe label, así que el modelo solo aprende de lo aprobado y no sabes cuántos buenos rechazas. Solución: una porción de exploración, ≈ 1 % de lo que el modelo rechazaría con riesgo medio (score menor a 0.90; nunca rechazos de reglas) va a step-up, con propensity 0.01 en el log; al entrenar, cada fila pesa 100.' },
    { id: 'c09-13', kind: 'numero', q: '¿Cuánto cuesta la exploración y cuándo “da dinero”?',
      a: '≈ 200 pagos/día (1 % de ≈ 20k rechazos del modelo). Con 40 % de fraude en la banda: fraude que pasa 3DS ≈ US$1,200/día + abandono ≈ US$135 − los US$900 que habría costado rechazar a los buenos ≈ <b>US$435/día ≈ US$13k/mes</b>, como toda la infra. Equilibrio: f × 0.20 × 75 = (1 − f) × 0.85 × 7.5 → f ≈ 30 %; si la banda tiene menos fraude, el umbral de rechazo está bajo.' },
    { id: 'c09-14', kind: 'concepto', q: '¿Por qué no basta log-and-wait como en c08?',
      a: 'El snapshot logueado sirve para las features que ya existen, pero una feature nueva esperaría log <b>y</b> madurez de labels: ≈ 4–6 meses. Se reconstruye con backfill point-in-time desde el log de eventos, con el mismo módulo de definiciones que el camino online, y un test de paridad la compara con el snapshot.' },
    { id: 'c09-15', kind: 'concepto', q: 'Desbalance de 1 en 1,250: ¿qué haces?',
      a: 'Submuestreo de negativos (p. ej. 2 % con peso 50: ≈ 37 M filas de 6 meses), pesos que lo compensan y <b>calibración</b> en una cohorte madura sin submuestrear. El desbalance se resuelve en el umbral y la evaluación, no con focal loss.' },
    { id: 'c09-16', kind: 'numero', q: 'Recall por conteo vs por valor: A atrapa 70 % de los fraudes y 50 % del valor; B, 60 % y 75 %. ¿Cuál?',
      a: 'B. Con 1,000 fraudes que suman US$45,000, B evita US$33,750 contra US$22,500 de A: US$11,250 más por cohorte con la misma fricción. El recall por conteo premia atrapar el card testing de US$1.' },
    { id: 'c09-17', kind: 'numero', q: 'Champion/challenger: ¿alcanza 1 % del tráfico por un mes?',
      a: '3 M transacciones, ≈ 2,400 fraudes. Error estándar ≈ √(0.0008/3 M + 0.0008/297 M) ≈ 1.6 × 10<sup>−5</sup>; un 10 % relativo es 8 × 10<sup>−5</sup> → z ≈ 4.9. Por conteo alcanza; en dólares hay más varianza. El cuello de botella es esperar 60–90 días de madurez.' },
    { id: 'c09-18', kind: 'concepto', q: 'Unidad de aleatorización del challenger y métrica primaria.',
      a: 'La <b>tarjeta</b> (hash del fingerprint): la misma tarjeta siempre ve la misma política y sus features de velocidad no mezclan políticas. Métrica: costo por 1,000 transacciones <b>asignadas</b> al brazo (no aprobadas), con guardrails de rechazo, step-up, aprobación del emisor y latencia.' },
    { id: 'c09-19', kind: 'numero', q: 'Scoring en CPU: ¿cuántas máquinas?',
      a: '2,000 TPS × ≈ 3 ms = 6 núcleos; al 50 % → 12 vCPU por zona (cada zona aguanta el pico) → 2 × c7i.2xlarge + 1 de N+1 = 3 por zona, 6 en total ≈ US$1.6k/mes.' },
    { id: 'c09-20', kind: 'numero', q: 'Online store: ¿qué lo dimensiona y cuánto mide?',
      a: 'La memoria, no los comandos (≈ 20k/s, aunque los scripts tocan ≈ 190 keys por pago). ≈ 80 M entidades × agregados (≈ 21 GB) + features diarias (≈ 10 GB) + contadores (≈ 1.8 GB) + guardias (≈ 0.4 GB) + caché de decisiones (≈ 1.8 GB) ≈ 35 GB × 1.3 ≈ <b>46 GB</b> → 4 shards de cache.r7g.xlarge × 2 copias.' },
    { id: 'c09-21', kind: 'concepto', q: 'Flink: cinco detalles para no romperse en silencio.',
      a: 'Event time con watermarks; eventos tardíos que actualizan su bucket (no se descartan); upserts del valor absoluto guardados por event time (un reproceso no pisa un valor más nuevo); estado acotado en RocksDB con checkpoints; hot keys (comercios grandes, CGNAT) pre-agregadas.' },
    { id: 'c09-22', kind: 'tradeoff', q: 'Fail-open vs fail-closed cuando el scoring no contesta.',
      a: 'Por segmento: abierto (aprobar si ninguna regla disparó, con montos máximos) en bajo y medio riesgo; step-up obligatorio en bienes digitales caros. Vive en la política versionada del scoring (modo solo reglas) y en la config del orquestador (si el scoring no contesta); nunca “rechazar todo” ni “aprobar todo” en alto riesgo.' },
    { id: 'c09-23', kind: 'concepto', q: 'Las 8 alertas del caso.',
      a: '<code>FraudScoreLatencyHigh</code>, <code>FraudFallbackActive</code>, <code>FeatureFreshnessLag</code>, <code>DeclineRateSpike</code>, <code>StepUpRateSpike</code>, <code>ScoreDistributionShift</code>, <code>RulesEngineErrors</code> y <code>ChargebackRateRising</code> (la única atrasada: compara cohortes a la misma edad).' },
    { id: 'c09-24', kind: 'concepto', q: '¿Cómo sabes hoy que el modelo empeoró si el label tarda 60 días?',
      a: 'Señales adelantadas: distribución del score y features (minutos), tasas de rechazo y step-up por segmento (minutos), declinaciones del emisor y éxito de 3DS (minutos a horas), revisión manual (horas), reportes de fraude del emisor (días). Confirmación: contracargos por cohorte a la misma edad.' },
    { id: 'c09-25', kind: 'tradeoff', q: '¿Qué palanca vale más: +1 pp de recall o −0.1 pp de rechazos de buenos?',
      a: '+1 pp de recall en dólares ≈ US$108k/mes. −0.1 pp de rechazos de buenos ≈ 300k pagos/mes × US$7.5 ≈ <b>US$2.25 M/mes</b>. La palanca grande es la fricción; la infraestructura (≈ US$10–15k/mes) es ruido.' },
    { id: 'c09-26', kind: 'trampa', q: 'Un comercio hace un flash sale y DeclineRateSpike dispara. ¿Cómo lo distingues de un ataque?',
      a: 'En una venta sube la velocidad del <b>comercio</b>, no la de cada <b>tarjeta</b>; los dispositivos tienen historia y el emisor aprueba. En un card testing: muchas tarjetas por dispositivo o IP, montos chicos y declinaciones del emisor (CVV, tarjeta inválida). Features por comercio normalizadas contra su línea base y un calendario de eventos.' },
    { id: 'c09-27', kind: 'frase', q: '¿Cómo abres el caso en inglés?',
      a: '“Before designing anything, I’d like to frame this in money: how much we lose today, what we can do with a risky payment besides declining it, and what it costs to decline a good customer. I assume the check runs inside the authorization, so it has tens of milliseconds and must fail safely.”' },
    { id: 'c09-28', kind: 'frase', q: '¿Cómo explicas en inglés por qué step-up y no rechazo?',
      a: '“With fraud at eight basis points by count, almost everything we decline is a good customer, so declining one percent of traffic costs more than all the fraud we see. The model mostly steps up the riskiest band and only declines at high probability or high ticket.”' },
  ];

